_CODE = ("", "Si allegano i documenti indicati in elenco.", "",
         "Il presente atto è redatto in formato digitale e sottoscritto con firma qualificata.", "",
         "Per ogni chiarimento è possibile rivolgersi all'ufficio nei giorni di apertura al pubblico.", "",
         "Distinti saluti.", "", "Luogo e data come da firma digitale.")


def _componi(dati: tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]) -> tuple[str, ...]:
    """Dieci testi: titolo (5 forme), corpo (4 casi) e intestazione diversi, con maiuscole, numero e lunghezza variabili."""
    titoli, corpi, uffici = dati
    testi: list[str] = []
    for i in range(10):
        titolo = titoli[i % len(titoli)]
        titolo = titolo.upper() if i % 3 == 0 else titolo
        corpo = corpi[i % len(corpi)].format(p=_PERSONE[i])
        righe = [uffici[i % len(uffici)], titolo]
        if i % 2:
            righe.append(f"Prot. n. {1000 + 137 * i}/2026")
        righe.append(corpo)
        if _CODE[i]:
            righe.append(_CODE[i])
        testi.append("\n".join(righe))
    return tuple(testi)


VARIANTI: dict[str, tuple[str, ...]] = {regola_id: _componi(dati) for regola_id, dati in _DATI_VARIANTI.items()}
